import pickle

def linear_interpolation(data_list, target_length):
    if not data_list:
        return []
    if len(data_list) == 1:
        return [data_list[0]] * target_length

    interpolated_data = []
    step_size = (len(data_list) - 1) / (target_length - 1) if target_length > 1 else 0

    for i in range(target_length):
        exact_pos = i * step_size
        lower_bound = int(exact_pos)
        upper_bound = min(lower_bound + 1, len(data_list) - 1)
        fraction = exact_pos - lower_bound

        val = data_list[lower_bound] * (1 - fraction) + data_list[upper_bound] * fraction
        interpolated_data.append(val)

