import pickle

def linear_interpolation(data_list, target_length):
    if not data_list:
        return []
    if len(data_list) == 1:
        return [data_list[0]] * target_length

    interpolated_data = []
    step_size = (len(data_list) - 1) / (target_length - 1) if target_length > 1 else 0

    for i in range(target_length):
        exact_pos = i * step_size
        lower_bound = int(exact_pos)
        upper_bound = min(lower_bound + 1, len(data_list) - 1)
        fraction = exact_pos - lower_bound

        val = data_list[lower_bound] * (1 - fraction) + data_list[upper_bound] * fraction
        interpolated_data.append(val)

    return interpolated_data

def search_and_replace(data_struct, target_val, replacement_val):
    if isinstance(data_struct, list):
        return [search_and_replace(item, target_val, replacement_val) for item in data_struct]
    elif isinstance(data_struct, dict):
        return {k: search_and_replace(v, target_val, replacement_val) for k, v in data_struct.items()}
    elif isinstance(data_struct, tuple):
        return tuple(search_and_replace(item, target_val, replacement_val) for item in data_struct)
    elif data_struct == target_val:
        return replacement_val
    return data_struct

def process_pickle_data(file_path_1, file_path_2, file_path_3, out_path_1, out_path_2, interp_len, search_term, replace_term):
    with open(file_path_1, 'rb') as f1:
        data1 = pickle.load(f1)

    with open(file_path_2, 'rb') as f2:
        data2 = pickle.load(f2)

    with open(file_path_3, 'rb') as f3:
        data3 = pickle.load(f3)

    interpolated_result = linear_interpolation(data1, interp_len)
    with open(out_path_1, 'wb') as out1:
        pickle.dump(interpolated_result, out1)

    replaced_result = search_and_replace(data2, search_term, replace_term)
    with open(out_path_2, 'wb') as out2:
        pickle.dump(replaced_result, out2)

